/**
 * The ids module: the generated file declaring the project's id manifest --
 * the Wendoo editor's permanent id allocations for its packs' vocabulary --
 * to the Wendoo VM extension, which the project compiles with the rest of its
 * code. This module writes it and reads it back.
 *
 * The text is line-structured. After two lines of comment it declares its
 * format as `// wendoo-ids-format <n>`, then the next id of each id space as
 * `// next-ids action <n> operator <n> atom <n>`, then a blank line, then the
 * namespace `wendooIds` carrying one call per allocation, in allocation order:
 * every tile's host-action id, then every operator's host-function id, then
 * every struct type's type-atom id with its field names, each at the position
 * that is its field id:
 *
 * ```ts
 * namespace wendooIds {
 *     wendoo.mapActionId("actuator.chime.ring", 1024);
 *     wendoo.mapOperatorId("beacon.combine", 1024);
 *     wendoo.mapTypeIds("Beacon", 1024, ["x", "y"]);
 * }
 * ```
 *
 * Every name is a JSON string literal with every character outside printable
 * ASCII escaped, so the text is ASCII and each literal stays on its line.
 */
import type { MakeCodeIdEntry, MakeCodeIdManifest, MakeCodeManifestReading } from "@wendoo/makecode-session";
import { MakeCodeManifestProblemCode } from "@wendoo/makecode-session";

/** Name of the ids module, relative to the simulator extension's folder in the project. */
export const IDS_MODULE_FILE = "ids.g.ts";

/** Format of the ids module this build writes, and the newest it reads. */
export const IDS_MODULE_FORMAT = 1;

/** The line declaring the format. */
const FORMAT_LINE = /^\/\/ wendoo-ids-format (\d+)$/;

/** The line declaring the next id of each space. */
const WATERMARK_LINE = /^\/\/ next-ids action (\d+) operator (\d+) atom (\d+)$/;

/** The start of every line, its indent removed, declaring an allocation. */
const ENTRY_START = "wendoo.map";

/** A string literal as a capturing pattern. */
const LITERAL = String.raw`("(?:[^"\\]|\\.)*")`;

/** A line, its indent removed, declaring a tile's host-action id. */
const ACTION_LINE = new RegExp(String.raw`^wendoo\.mapActionId\(${LITERAL}, (\d+)\);$`);

/** A line, its indent removed, declaring an operator's host-function id. */
const OPERATOR_LINE = new RegExp(String.raw`^wendoo\.mapOperatorId\(${LITERAL}, (\d+)\);$`);

/** A line, its indent removed, declaring a struct type's atom and field names. */
const TYPE_LINE = new RegExp(String.raw`^wendoo\.mapTypeIds\(${LITERAL}, (\d+), \[(.*)\]\);$`);

/** Indent of an allocation's line inside the namespace. */
const ENTRY_INDENT = "    ";

/**
 * The text of the ids module declaring `manifest`. The same manifest always
 * yields the same text, which {@link readIdsModule} reads back to it.
 *
 * @param manifest - The allocation to declare.
 */
export function writeIdsModule(manifest: MakeCodeIdManifest): string {
  const { next } = manifest;
  const lines = [
    "// Generated by the Wendoo simulator extension from the Wendoo editor's id allocations.",
    "// Every id here is permanent: the Wendoo editor appends new ones and never changes one.",
    `// wendoo-ids-format ${IDS_MODULE_FORMAT}`,
    `// next-ids action ${next.action} operator ${next.operator} atom ${next.atom}`,
    "",
    "namespace wendooIds {",
  ];
  for (const entry of manifest.actions) {
    lines.push(`${ENTRY_INDENT}wendoo.mapActionId(${asciiLiteral(entry.name)}, ${entry.id});`);
  }
  for (const entry of manifest.operators) {
    lines.push(`${ENTRY_INDENT}wendoo.mapOperatorId(${asciiLiteral(entry.name)}, ${entry.id});`);
  }
  for (const type of manifest.types) {
    const fields = type.fields.map(asciiLiteral).join(", ");
    lines.push(`${ENTRY_INDENT}wendoo.mapTypeIds(${asciiLiteral(type.name)}, ${type.atom}, [${fields}]);`);
  }
  lines.push("}");
  return `${lines.join("\n")}\n`;
}

/**
 * Read the manifest an ids module declares. Never throws: text declaring no
 * format reads as no manifest under `UNREADABLE`, and one declaring a newer
 * format under `FORMAT_NEWER`; an allocation line that does not follow the
 * format, a second line naming one registration, or a damaged watermark line
 * is reported under `ENTRY_MALFORMED`, and the rest is read -- the
 * watermarks then derived from the entries read. Line ends may be `\n` or
 * `\r\n`.
 *
 * @param text - The module's text.
 */
export function readIdsModule(text: string): MakeCodeManifestReading {
  const lines = text.split(/\r?\n/);
  const declared = lines.map((line) => FORMAT_LINE.exec(line)).find((match) => match !== null);
  const format = declared ? Number(declared[1]) : undefined;
  if (format !== IDS_MODULE_FORMAT) {
    const problem =
      format !== undefined && format > IDS_MODULE_FORMAT
        ? MakeCodeManifestProblemCode.FORMAT_NEWER
        : MakeCodeManifestProblemCode.UNREADABLE;
    return { manifest: null, problem };
  }
  let malformed = false;
  const manifest: MakeCodeIdManifest = {
    actions: [],
    operators: [],
    types: [],
    next: { action: 0, operator: 0, atom: 0 },
  };
  const watermarks = lines.map((line) => WATERMARK_LINE.exec(line)).find((match) => match !== null);
  for (const line of lines.map((raw) => raw.trim())) {
    if (!line.startsWith(ENTRY_START)) continue;
    if (!readEntry(line, manifest)) malformed = true;
  }
  if (watermarks) {
    manifest.next = { action: Number(watermarks[1]), operator: Number(watermarks[2]), atom: Number(watermarks[3]) };
  } else {
    malformed = true;
    manifest.next = {
      action: nextAbove(manifest.actions.map((entry) => entry.id)),
      operator: nextAbove(manifest.operators.map((entry) => entry.id)),
      atom: nextAbove(manifest.types.map((type) => type.atom)),
    };
  }
  return malformed ? { manifest, problem: MakeCodeManifestProblemCode.ENTRY_MALFORMED } : { manifest };
}

/** Adds the allocation `line` declares to `manifest`; returns whether it followed the format and named a registration not yet read. */
function readEntry(line: string, manifest: MakeCodeIdManifest): boolean {
  const action = ACTION_LINE.exec(line);
  if (action) return addEntry(manifest.actions, action[1], action[2]);
  const operator = OPERATOR_LINE.exec(line);
  if (operator) return addEntry(manifest.operators, operator[1], operator[2]);
  const type = TYPE_LINE.exec(line);
  if (!type) return false;
  const name = parseLiteral(type[1]);
  const fields = parseFieldNames(type[3]);
  if (name === undefined || fields === undefined) return false;
  if (manifest.types.some((entry) => entry.name === name)) return false;
  manifest.types.push({ name, atom: Number(type[2]), fields });
  return true;
}

/** Adds the entry `literal` and `id` spell to `entries`; returns whether the literal reads and names no entry already there. */
function addEntry(entries: MakeCodeIdEntry[], literal: string, id: string): boolean {
  const name = parseLiteral(literal);
  if (name === undefined || entries.some((entry) => entry.name === name)) return false;
  entries.push({ name, id: Number(id) });
  return true;
}

/** One above the highest of `ids`, or 0 when there are none. */
function nextAbove(ids: readonly number[]): number {
  return ids.reduce((next, id) => Math.max(next, id + 1), 0);
}

/** The field names the comma-separated literals of `list` spell, or `undefined` when they are not all string literals. */
function parseFieldNames(list: string): string[] | undefined {
  try {
    const value: unknown = JSON.parse(`[${list}]`);
    return Array.isArray(value) && value.every((field) => typeof field === "string") ? value : undefined;
  } catch {
    return undefined;
  }
}

/** `text` as a JSON string literal whose every character outside printable ASCII is escaped. */
function asciiLiteral(text: string): string {
  return JSON.stringify(text).replace(
    /[\u007f-\uffff]/g,
    (character) => `\\u${character.charCodeAt(0).toString(16).padStart(4, "0")}`
  );
}

/** The string the JSON string literal `literal` denotes, or `undefined` when it is not one. */
function parseLiteral(literal: string): string | undefined {
  try {
    const value: unknown = JSON.parse(literal);
    return typeof value === "string" ? value : undefined;
  } catch {
    return undefined;
  }
}
